400','500'),2,'১০% ক্ষতি থেকে ৫% লাভে যেতে পার্থক্য ১৫% = ৬০ টাকা; ক্রয়মূল্য = ৬০ × ১০০/১৫ = ৪০০ টাকা।',false,'ok',96),array('mental','কোনো যান্ত্রিক গিয়ারের চাকা ছোট হলে সংযুক্ত অবস্থায় বড়টির চেয়ে ছোট চাকাটি কিভাবে ঘুরবে?',array('আস্তে','জোরে','একইভাবে','কোনোটিই নয়'),1,'সংযুক্ত গিয়ারের পরিধিতে বেগ সমান হয়; ছোট চাকার পরিধি কম বলে এটি বেশি পাক ঘোরে, অর্থাৎ জোরে ঘুরবে।',false,'ok',97),array('mental','১৫ মিটার লম্বা একটি স্কেলের একপ্রান্তে ১০ কেজি ওজন বাঁধা হয়েছে। একই প্রান্ত থেকে স্কেলের দৈর্ঘ্যের ৩ : ২ অনুপাতে একটি পেরেক লাগানো আছে। অপর প্রান্তে কতকেজি ওজন দিলে স্কেলের ভারসাম্য থাকবে?',array('৪৫','৩০','১৫','৫'),2,'পেরেক ৩ : ২ অনুপাতে বসলে ১০ কেজির প্রান্ত থেকে দূরত্ব ৯ মি, অপর প্রান্ত ৬ মি। ভ্রামক সমান: ১০ × ৯ = W × ৬ ⇒ W = ১৫ কেজি (স্কেলের ওজন উপেক্ষিত)।',false,'ok',98),array('math','একটি থলিতে 3 টি সবুজ এবং 2 টি লাল বল আছে। অপর একটি থলিতে 2 টি সবুজ এবং 5 টি লাল বল আছে। নিরপেক্ষভাবে প্রত্যেক থলি থেকে একটি করে বল তোলা হলো। দুইটি বলের মধ্যে অন্তত একটি সবুজ হওয়ার সম্ভাব্যতা কত?',array('5/7','2/7','5/12','1/4'),0,'কোনো সবুজ না ওঠার সম্ভাবনা = (2/5) × (5/7) = 2/7; অন্তত একটি সবুজ = 1 – 2/7 = 5/7।',false,'ok',99),array('math','PQR ত্রিভুজের ∠Q = 90° এবং ∠P = 2∠R হলে নিচের কোনটি সঠিক?',array('PR = 2QR','PQ = 2PR','PR = 2PQ','QR = 2PQ'),2,'∠P + ∠R = 90° ও ∠P = 2∠R ⇒ ∠R = 30°, ∠P = 60°। ৩০° কোণের বিপরীত বাহু PQ অতিভুজ PR-এর অর্ধেক, তাই PR = 2PQ।',false,'ok',100));
